require __DIR__ . '/includes/auth.php'; if (!eh_cliente()) redirecionar('dashboard.php');
$itens=itens_carrinho($dados); if (!$itens) { flash('Adicione produtos antes de finalizar.','erro'); redirecionar('loja.php'); }
$erros=[]; $v = ['pagamento'=>'cartao', 'cep'=>'', 'rua'=>'', 'numero_endereco'=>'', 'complemento'=>'', 'bairro'=>'', 'cidade'=>'', 'uf'=>'', 'titular'=>'', 'numero_cartao'=>'', 'validade'=>'', 'cvv'=>''];
if ($_SERVER['REQUEST_METHOD']==='POST') {
  foreach ($v as $campo => $valor) $v[$campo] = trim($_POST[$campo] ?? '');
  $v['pagamento'] = $_POST['pagamento'] ?? 'cartao';
  if (!in_array($v['pagamento'], ['cartao', 'pix', 'boleto'], true)) $erros[]='Selecione uma forma de pagamento válida.';
  foreach (['cep'=>'CEP', 'rua'=>'Rua', 'numero_endereco'=>'Número', 'bairro'=>'Bairro', 'cidade'=>'Cidade', 'uf'=>'UF'] as $campo => $rotulo) if ($v[$campo] === '') $erros[]='Informe ' . $rotulo . ' para a entrega.';
  if ($v['pagamento'] === 'cartao') {
    $numero=preg_replace('/\D/','',$v['numero_cartao']); $cvv=preg_replace('/\D/','',$v['cvv']);
    if ($v['titular']==='') $erros[]='Informe o nome impresso no cartão.'; if (strlen($numero)<13 || strlen($numero)>19) $erros[]='Informe um número de cartão de exemplo válido.'; if (!preg_match('/^\d{2}\/\d{2}$/',$v['validade'])) $erros[]='Use a validade no formato MM/AA.'; if (strlen($cvv)<3 || strlen($cvv)>4) $erros[]='Informe o código de segurança.';
  }
  if (!$erros) { $endereco = array_intersect_key($v, array_flip(['cep','rua','numero_endereco','complemento','bairro','cidade','uf'])); $resultado=finalizar_pedido($dados,(int)$_SESSION['usuario_id'],$v['pagamento'],$endereco); if($resultado['erro']) $erros[]=$resultado['erro']; else { flash('Pedido #' . $resultado['pedido_id'] . ' confirmado com pagamento simulado.'); redirecionar('pedidos.php'); } }
}
$pagina='checkout'; $titulo='Pagamento'; include __DIR__ . '/includes/header.php';
?>
